import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-06-10","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-06-10","outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-06-10.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-06-10.md","lastUpdated":null}'),i={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-06-10.md"};function l(s,e,n,c,p,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<p>Now I&#39;ll format the meeting summary in Chinese.--- title: Ceph RGW Refactoring Meeting 2026-06-10 date: 2026-07-10 updated: 2026-07-11 tags:</p><ul><li>RGW</li><li>加密</li><li>去重</li><li>会议纪要</li><li>对象存储 categories:</li><li>视频总结 subtitle: Ceph_RGW_Refactoring_Meeting_2026-06-10</li></ul><hr><h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph RGW（radosgw）重构会议主要围绕多个待审查 PR 的进展、compression 与 encryption 在对象生命周期迁移中的交互问题、dedupe（去重）与 compression 属性的冲突、cloud restore 队列的锁机制优化，以及 KMIP 后端对 SSE-S3 的支持与 lib KMIP fork 维护策略等议题展开讨论。</p><h2 id="主要议题与讨论" tabindex="-1">主要议题与讨论 <a class="header-anchor" href="#主要议题与讨论" aria-label="Permalink to &quot;主要议题与讨论&quot;">​</a></h2><h3 id="_1-生命周期迁移中的-compression-与-encryption" tabindex="-1">1. 生命周期迁移中的 compression 与 encryption <a class="header-anchor" href="#_1-生命周期迁移中的-compression-与-encryption" aria-label="Permalink to &quot;1. 生命周期迁移中的 compression 与 encryption&quot;">​</a></h3><p>第一位与会者介绍了几个需要 re-review 的 PR：</p><ul><li><strong>PR 67725</strong>：在 life cycle transition（生命周期迁移）过程中支持对象的 compressed 与 decompressed 处理。由于 main 分支近期合入了 GCM 支持，该 PR 做了小幅重构以适配，目前需要重新审查。</li><li><strong>PR 69336</strong>：针对已合入的 GCM 相关工作的 follow-up。Sage 提出了几点 concern，作者据此创建了此 PR 进行修正，Sage 已给出 approval，只待 QA 测试通过后在 umbrella 分支切出前合入。</li></ul><p>关于 <strong>umbrella release / umbrella branch</strong> 的切分计划，与会者确认该分支尚未切出（此前有人误以为上周已完成）。这意味着 Marcel 暂时不需要为 SSE-S3 cache（KMS cache）做 backport。若最终没有 umbrella release，则应争取在分支切出前尽快合入相关 PR。</p><h3 id="_2-copy-object-的-backport-与-encryption-交互" tabindex="-1">2. Copy object 的 backport 与 encryption 交互 <a class="header-anchor" href="#_2-copy-object-的-backport-与-encryption-交互" aria-label="Permalink to &quot;2. Copy object 的 backport 与 encryption 交互&quot;">​</a></h3><ul><li><strong>PR 69277</strong>：backport 了 Marcus 完成的 copy object 工作，附带两个 follow-up PR 以及 Casey 提供的用于测试 compress + encrypt 功能的 QA 测试。</li></ul><p>Gabby（下称去重相关工程师）此前对该 PR 存在误解，以为 server-side copy 是通过将 manifest 从 source 链接到 target 实现的，因而不清楚 encryption 如何工作。会上澄清：copy object 实际执行的是 <strong>full object copy（完整对象复制）</strong>，对象会被复制一份，而非共享 manifest。该功能已于去年 12 月合入 main，已存在约六个月。</p><h3 id="_3-dedupe-与-compression-属性的冲突-关键议题" tabindex="-1">3. dedupe 与 compression 属性的冲突（关键议题） <a class="header-anchor" href="#_3-dedupe-与-compression-属性的冲突-关键议题" aria-label="Permalink to &quot;3. dedupe 与 compression 属性的冲突（关键议题）&quot;">​</a></h3><p>去重工程师提出核心关切：<strong>对象在创建后能否改变 compression 状态？</strong></p><ul><li>结论：通过 copy object 不能改变，但通过 <strong>life cycle transition 可以</strong>（PR 67725 允许将对象解压后用新的 compression scheme 重新压缩，这本身是一个用户需求）。</li><li>该行为对 dedupe 构成潜在风险：如果某对象是 <strong>dedupe 的 source</strong>，其 compression 属性被改变，而 target 仍假设与 source 具有相同属性，就会导致 <strong>数据损坏（data corruption）</strong>。</li><li>提出的限制方案：若对象带有标识其为 dedupe source 的属性，则跳过压缩/重压缩逻辑，<strong>保持其 compression 属性不变</strong>。这是一个简单的检查。作者同意在 PR 中加入该 guidance，请去重工程师在 PR 上补充相应 comment。</li></ul><p>进一步讨论澄清了迁移的本质：将对象数据从一个 storage class（对应一个 pool）迁移到另一个 storage class（可能在另一个 pool），过程中会 <strong>删除本地原对象并生成新对象</strong>，而非原地修改现有对象的属性。去重工程师明确表示，只要是&quot;删除旧对象 + 生成新对象&quot;的模式，就不影响 dedupe，可以接受。</p><p>需要进一步同步确认的细节：override head 时是否 <strong>保留原有的 rift tag（etag）还是生成新的</strong>。作者将线下与去重工程师同步。此外，Marcus 相关工作尚未合入 main（等待 Matt review），作者计划将 PR 67725 rebase 到该工作之上，通过 Teuthology（字幕中&quot;Cephology&quot;为音译误写）运行 dedupe 与 lifecycle 相关测试验证。</p><h3 id="_4-cloud-restore-的-cls-lock-与-shard-锁优化" tabindex="-1">4. Cloud restore 的 CLS lock 与 shard 锁优化 <a class="header-anchor" href="#_4-cloud-restore-的-cls-lock-与-shard-锁优化" aria-label="Permalink to &quot;4. Cloud restore 的 CLS lock 与 shard 锁优化&quot;">​</a></h3><ul><li><p><strong>PR 69312</strong>：对上周由某用户创建的 cloud restore tracker 的 follow-up。新增了 co-routine（协程）支持，并修改了 FIFO queue 中 shard part 上锁的 timeout 机制。作者借鉴了 Casey 在 multi-part 上锁机制中&quot;任务仍在运行则续租 lock&quot;的做法，将其调整以适配 shard part。</p></li><li><p>机制说明：restore 使用 CLS lock 在处理某个 shard 期间持有锁，防止其他 RGW 重复处理同一份工作，这与 multisite 使用 lease 的方式非常相似。</p></li><li><p>压力测试结果：作者构造了所有对象都落入单个 shard（含数百个 part）的场景（该场景与同一用户上报的另一 ticket 相关），验证了改动能够 <strong>持续取得 durable progress</strong>。</p></li><li><p>发现的问题：Sumaya 最初实现时假设遍历整个 shard 只需 90 秒，这在 QA 和小规模环境下成立；但在需要恢复数百万对象的大规模环境下，<strong>90 秒远不足以遍历完整个 shard part</strong>。</p></li><li><p>后续改进方向：Casey 提到自己在用 C++20 co-routines 原型化 metadata sync 时曾写过一个 <code>with lease</code> 算法，当时因时间压力未引入 multi-part。他将在 PR 中分享链接，未来可考虑将该续租模式抽象为可被其他函数复用的 helper。</p></li></ul><h3 id="_5-tentacle-backport-与-release-engineering-audit" tabindex="-1">5. Tentacle backport 与 release engineering audit <a class="header-anchor" href="#_5-tentacle-backport-与-release-engineering-audit" aria-label="Permalink to &quot;5. Tentacle backport 与 release engineering audit&quot;">​</a></h3><ul><li><p>copy object 的 Tentacle backport 及配套 S3 tests 已完成。Casey 添加了 &quot;need separate S3 test QA&quot; 标签，需要有人准备分支并针对这些测试跑 QA。作者将提供指向该 CI 分支的 Shaman build，Casey 将准备 sweep branch 并针对相应 packages 调度 QA。</p></li><li><p><strong>audit 争议</strong>：部分 backport PR 缺少对应的 tracker，作者尝试创建了几个，但检查用的 git bot 未能正确识别，可能需要 release engineering audit 的 override。与会者（包括 Casey、Adam、Eric）普遍认为当前的 audit 机制 <strong>帮助有限</strong>：其主要&quot;作用&quot;是每次推送变更都需反复请求批准 backport；PR comment 过于冗长，难以从中甄别真正 actionable 的内容。共识倾向依赖良好的 QA 测试覆盖率而非人工逐 commit 审查。有人认为一个仅作诊断提示（如&quot;你 backport 时漏了某个 commit&quot;）而不带 override 强制的机制才真正有用。此议题建议后续在 CSC 中讨论。</p></li><li><p><strong>merge window 限制</strong>：Tentacle 的 merge window 尚未开放，因此该 backport 暂时无法合入。预计会落在未来的 <strong>10.2.3</strong> 版本（已错过 10.2.2）。Casey 表达了希望能在 window 之外也进行 QA 与 merge 的诉求，否则会持续积压 backport 并面临 pending backport 之间的冲突处理，增加在单个 point release 中集中落地多个相关修复的难度。</p></li></ul><h3 id="_6-kmip-后端支持-sse-s3-与-lib-kmip-fork-维护" tabindex="-1">6. KMIP 后端支持 SSE-S3 与 lib KMIP fork 维护 <a class="header-anchor" href="#_6-kmip-后端支持-sse-s3-与-lib-kmip-fork-维护" aria-label="Permalink to &quot;6. KMIP 后端支持 SSE-S3 与 lib KMIP fork 维护&quot;">​</a></h3><p>Preeti（下称 KMIP 工程师）介绍了一个 draft PR：为 <strong>KMIP 后端新增 SSE-S3 支持</strong>，与现有 vault 后端行为一致——在 KMIP server 上创建一个 key，每个对象获得一个全新的 data encryption key，并存储于 bucket 的 attribute 中。</p><p>核心难题在于依赖库：</p><ul><li>Ceph 内置的 <strong>lib KMIP</strong> 相比 upstream 已严重过时，本次实现需要新增大量特性（如 encrypt/decrypt 支持）。</li><li>因此该 PR 在 lib KMIP 变更未合入前无法 merge，而 lib KMIP 的改动又因两边严重 diverge 而无法直接合回 Ceph 内的版本。</li><li>upstream 项目（Open KMIP 及其相关 repo）已基本停止维护（最后一次 commit 约在四年前，整个组织疑似已解散），与 Python bindings 面临相同困境，向上游提交 PR 已不现实。</li></ul><p>处理方向达成初步共识：</p><ul><li>Ceph 只能在自己的 fork 中承载这些改动。最初的 fork 由 <strong>Marcus Watts</strong> 完成，将请他参与 review，尤其是 KMIP 相关的具体部分；而 RGW 中更通用的 code flow 可由其他人协助 review。</li><li>关于如何管理 fork 的 pull-up 与后续改动，应作为第一步先行确定。KMIP 工程师将就此与 Marcus 联系。</li><li>该 PR 虽暂时无法 merge，但可以先行 review。作者计划将其中与 lib KMIP 无关的部分（如工作中顺带发现并修复的 bug、以及新增的 <strong>multi-threading</strong> 支持等 feature enhancement）拆分为独立 PR 先行审查；待 lib KMIP 维护方案达成一致后，再单独提交 SSE-S3 部分的 PR。</li></ul><h2 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h2><ul><li>PR 67725 将增加针对 dedupe source 对象的保护逻辑：若对象为 dedupe source，则保持其 compression 属性不变，跳过重压缩，以避免 target 数据损坏。</li><li>copy object 迁移采用&quot;迁移数据到新 pool + 删除本地原对象 + 生成新对象&quot;的模式，此模式不影响 dedupe，各方认可。</li><li>copy object 的 Tentacle backport 预计落地 10.2.3，暂无法进入当前 merge window。</li><li>KMIP 的 SSE-S3 支持依赖 lib KMIP fork，需先确定 fork 的维护策略；PR 中与 lib KMIP 无关的改动将拆分先行 review。</li><li>audit 机制的有效性问题建议提交 CSC 讨论。</li></ul><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>去重工程师：在 PR 67725 上补充 dedupe source 保护相关的 comment。</li><li>PR 67725 作者：据此调整 PR；线下与去重工程师同步 rift tag（etag）是保留还是新生成的问题；将 PR 67725 rebase 到 Marcus 未合入的 copy object 工作之上，通过 Teuthology 运行 dedupe 与 lifecycle 测试。</li><li>Casey：在 PR 69312 中分享 <code>with lease</code> 算法链接，供 shard/multi-part 锁续租 helper 复用参考。</li><li>Matthew：提供 copy object backport 的 Shaman build 链接。</li><li>Casey：准备 sweep branch 并针对提供的 packages 调度 QA。</li><li>KMIP 工程师：修订 SSE-S3 分支，拆分不依赖 lib KMIP 的部分为独立 PR；与 Marcus Watts 就 lib KMIP fork 的维护策略沟通。</li><li>Casey：在 Slack 上联系 Marcus，确保其看到被 tag 为 reviewer 的 KMIP PR。</li></ul>',32)])])}const h=t(i,[["render",l]]);export{g as __pageData,h as default};
